onInit() {
  this.updateTime()

  ensureStorageReady()
    .then(() => {
      // Storage 已初始化，直接使用缓存数据更新状态
      this.updateStatus()

      // 启动定时器：只更新时间，不重复读取 Storage
      if (!this.timer) {
        this.timer = setInterval(() => {
          this.updateTime()
          this.updateStatus()
        }, 1000)
      }
    })
    .catch((err) => {
      console.error('Failed to initialize storage on home:', err)
      this.updateStatus()

      if (!this.timer) {
        this.timer = setInterval(() => {
          this.updateTime()
          this.updateStatus()
        }, 1000)
      }
    })
},

